 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Full-width and full-height uniform lines are the grid's separators.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    cuts_r = [-1] + sep_rows + [h]
    cuts_c = [-1] + sep_cols + [w]
    regions = []
    for ri in range(len(cuts_r) - 1):
        r0, r1 = cuts_r[ri] + 1, cuts_r[ri + 1]
        if r0 >= r1:
            continue
        for ci in range(len(cuts_c) - 1):
            c0, c1 = cuts_c[ci] + 1, cuts_c[ci + 1]
            if c0 < c1:
                regions.append((r0, r1, c0, c1))
    # The most common non-separator color is the region background.
    sep_colors = {grid[r][0] for r in sep_rows} | {grid[0][c] for c in sep_cols}
    counts = {}
    for row in grid:
        for v in row:
            if v not in sep_colors:
                counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get) if counts else 0
    # Pick the region with the greatest number of cells differing from its background.
    def score(box):
        r0, r1, c0, c1 = box
        return sum(grid[r][c] != bg for r in range(r0, r1) for c in range(c0, c1))
    source = max(regions, key=score)
    r0, r1, c0, c1 = source
    tile = [row[c0:c1] for row in grid[r0:r1]]
    out = [row[:] for row in grid]
    for a, b, x, y in regions:
        for i in range(b - a):
            for j in range(y - x):
                out[a + i][x + j] = tile[i % len(tile)][j % len(tile[0])]
    return out
